import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/Chat.css";

const ChatPage = () => {
  const [conversations, setConversations] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    const fetchConversations = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/conversations/${user._id}`);
        setConversations(res.data);
      } catch (err) {
        console.error("Error fetching conversations:", err);
      }
    };

    if (user?._id) fetchConversations();
  }, [user]);

  const selectConversation = async (otherUserId) => {
    setSelectedUser(otherUserId);
    try {
      const res = await axios.get(`http://localhost:5000/api/messages/${user._id}/${otherUserId}`);
      setMessages(res.data);
    } catch (err) {
      console.error("Error fetching messages:", err);
    }
  };

  const sendMessage = async () => {
    if (!newMessage.trim()) return;

    try {
      const messageData = {
        senderId: user._id,
        receiverId: selectedUser,
        text: newMessage,
      };

      const res = await axios.post("http://localhost:5000/api/messages", messageData);
      setMessages((prev) => [...prev, res.data]);
      setNewMessage("");
    } catch (err) {
      console.error("Error sending message:", err);
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-sidebar">
        <h3>Conversations</h3>
        {conversations.map((conv) => {
          const otherUser = conv.members.find((id) => id !== user._id);
          return (
            <div
              key={conv._id}
              className={`chat-user ${selectedUser === otherUser ? "active" : ""}`}
              onClick={() => selectConversation(otherUser)}
            >
              {otherUser}
            </div>
          );
        })}
      </div>

      <div className="chat-main">
        <h3>Chat</h3>
        <div className="chat-messages">
          {messages.map((msg) => (
            <div
              key={msg._id}
              className={`chat-bubble ${msg.senderId === user._id ? "sent" : "received"}`}
            >
              {msg.text}
            </div>
          ))}
        </div>

        {selectedUser && (
          <div className="chat-input">
            <input
              type="text"
              placeholder="Type a message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
            />
            <button onClick={sendMessage}>Send</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatPage;
